//! 🛫️ Controlled Pack container framing, checksums, hashes and intrinsic chunks.
use super::*;
use crate::{KIND_SYMBOLS,KIND_DOCUMENT,KIND_CHUNK,KIND_CHUNK_TABLE,KIND_MANIFEST,KIND_END};
use protocol::value::native_encoding::NativeEncodeControl;
use protocol::value::{ValueError,ValueRefusalKind};
use std::mem::size_of;

struct Prefix{bytes:[u8;256],length:usize}
impl Prefix{
    fn new()->Self{Self{bytes:[0;256],length:0}}
    fn bytes(&mut self,bytes:&[u8])->Result<(),PackError>{let end=self.length.checked_add(bytes.len()).filter(|end|*end<=self.bytes.len()).ok_or(PackError::LimitExceeded{kind:ValueRefusalKind::InvariantViolated,limit:"Pack fixed prefix overflow"})?;self.bytes[self.length..end].copy_from_slice(bytes);self.length=end;Ok(())}
    fn varint(&mut self,mut value:u64)->Result<(),PackError>{loop{let mut byte=(value as u8)&127;value>>=7;if value!=0{byte|=128;}self.bytes(&[byte])?;if value==0{return Ok(())}}}
    fn span(&mut self,span:ByteRange)->Result<(),PackError>{self.varint(span.offset)?;self.varint(span.len)}
    fn slice(&self)->&[u8]{&self.bytes[..self.length]}
}

/// 📦️ A physical output owner with one caller control across all segments and its footer.
pub struct ControlledPackWriter{bytes:Vec<u8>,codec:CodecId,required_flags:u32,symbols_span:ByteRange,symbol_count:u64,chunks:Vec<ChunkTableEntry>,document_hash:semio_framework_hash::Hasher,maximum_file:u64,maximum_segment:u64}
impl ControlledPackWriter{
    /// 🪪️ Admits the literal header and live document hash state before ownership.
    pub fn begin(options:&WriteOptions,limits:&PackLimits,control:&mut NativeEncodeControl<'_>)->Result<Self,PackError>{
        control.checkpoint().map_err(PackError::ValueRefusal)?;let required_flags=options.required_flags|if options.codec.0!=0{REQUIRED_COMPRESSED}else{0};if required_flags&!REQUIRED_KNOWN_MASK!=0{return Err(PackError::UnknownRequiredFlags(required_flags&!REQUIRED_KNOWN_MASK))}if options.codec.0>1{return Err(PackError::UnsupportedCodec(options.codec.0))}
        control.charge(size_of::<semio_framework_hash::Hasher>()).map_err(PackError::ValueRefusal)?;let header=Header{version_major:FORMAT_VERSION_MAJOR,version_minor:FORMAT_VERSION_MINOR,required_flags,optional_flags:options.optional_flags};let mut owner=Self{bytes:Vec::new(),codec:options.codec,required_flags,symbols_span:ByteRange{offset:0,len:0},symbol_count:0,chunks:Vec::new(),document_hash:semio_framework_hash::Hasher::new(),maximum_file:limits.max_file_len,maximum_segment:limits.max_segment_len};let bytes=header.write_bytes_sync();owner.append(&bytes,control)?;Ok(owner)
    }
    /// 📍️ Returns the exact emitted physical byte position.
    pub fn position(&self)->u64{self.bytes.len()as u64}
    fn append(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{let end=(self.bytes.len()as u64).checked_add(bytes.len()as u64).ok_or(PackError::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"Pack output exceeds max_file_len"})?;if end>self.maximum_file{return Err(PackError::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"Pack output exceeds max_file_len"});}control.append_bytes(&mut self.bytes,bytes).map_err(PackError::ValueRefusal)}
    fn hash(hasher:&mut semio_framework_hash::Hasher,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{control.scoped_stage(|control|{control.begin_stage(bytes.len())?;for fragment in bytes.chunks(65536){hasher.update(fragment);control.advance(fragment.len())?;}Ok::<_,ValueError>(())}).map_err(PackError::ValueRefusal)}
    fn crc(crc:&mut crate::codec::Crc32cCursor,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{control.scoped_stage(|control|{control.begin_stage(bytes.len())?;for fragment in bytes.chunks(65536){crc.update_page(fragment);control.advance(fragment.len())?;}Ok::<_,ValueError>(())}).map_err(PackError::ValueRefusal)}
    /// 🔤️ Emits the already admitted literal symbol table without reconstructing strings.
    pub fn symbols(&mut self,payload:&[u8],count:u64,control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{let start=self.position();self.segment(KIND_SYMBOLS,payload,control)?;self.symbols_span=ByteRange{offset:start,len:self.position()-start};self.symbol_count=count;Ok(())}
    /// 🖇️ Frames a segment through its declared codec and controlled CRC/content hash.
    pub fn segment(&mut self,kind:u8,payload:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{
        if payload.len()as u64>self.maximum_segment{return Err(PackError::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"Pack output exceeds max_segment_len"})}control.checkpoint().map_err(PackError::ValueRefusal)?;
        let owned=match self.codec.0{0=>None,1=>Some(crate::codec::deflate_compress_controlled(payload,control)?),other=>return Err(PackError::UnsupportedCodec(other))};let stored=owned.as_deref().unwrap_or(payload);if stored.len()as u64>self.maximum_segment{return Err(PackError::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"Pack stored segment exceeds max_segment_len"})}let mut prefix=Prefix::new();prefix.bytes(&[kind,if owned.is_some(){1|(self.codec.0<<1)}else{0}])?;prefix.varint(stored.len()as u64)?;if owned.is_some(){prefix.varint(payload.len()as u64)?;}let mut crc=crate::codec::Crc32cCursor::new();Self::crc(&mut crc,prefix.slice(),control)?;Self::crc(&mut crc,stored,control)?;self.append(prefix.slice(),control)?;self.append(stored,control)?;self.append(&crc.finish().to_le_bytes(),control)?;if kind==KIND_DOCUMENT{Self::hash(&mut self.document_hash,payload,control)?;}Ok(())
    }
    /// 🧱️ Emits an intrinsic raw chunk and admits its physical index entry before publishing it.
    pub fn chunk(&mut self,payload:&[u8],control:&mut NativeEncodeControl<'_>)->Result<ChunkId,PackError>{
        if payload.len()as u64>self.maximum_segment{return Err(PackError::LimitExceeded{kind:ValueRefusalKind::WorkLimit,limit:"Pack chunk exceeds max_segment_len"})}let id=ChunkId(u32::try_from(self.chunks.len()).map_err(|_|PackError::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"Pack chunk index exceeds u32"})?);control.charge(size_of::<ChunkTableEntry>()).map_err(PackError::ValueRefusal)?;let target=self.chunks.len().checked_add(1).ok_or(PackError::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"Pack chunk index allocation"})?;check_allocation_layout::<ChunkTableEntry>(target,"Pack chunk index allocation")?;self.chunks.try_reserve_exact(1).map_err(|_|PackError::LimitExceeded{kind:ValueRefusalKind::AllocationFailed,limit:"Pack chunk index allocation"})?;control.charge(size_of::<semio_framework_hash::Hasher>()).map_err(PackError::ValueRefusal)?;let mut hash=semio_framework_hash::Hasher::new();Self::hash(&mut hash,payload,control)?;let mut payload_crc=crate::codec::Crc32cCursor::new();Self::crc(&mut payload_crc,payload,control)?;let mut prefix=Prefix::new();prefix.bytes(&[KIND_CHUNK,0])?;prefix.varint(payload.len()as u64)?;let offset=self.position()+prefix.length as u64;let mut segment_crc=crate::codec::Crc32cCursor::new();Self::crc(&mut segment_crc,prefix.slice(),control)?;Self::crc(&mut segment_crc,payload,control)?;self.append(prefix.slice(),control)?;self.append(payload,control)?;self.append(&segment_crc.finish().to_le_bytes(),control)?;self.chunks.push(ChunkTableEntry{offset,stored_len:payload.len()as u64,raw_len:payload.len()as u64,crc32:payload_crc.finish(),blake3:*hash.finalize().as_bytes()});Ok(id)
    }
    fn raw_segment(&mut self,kind:u8,payload:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),PackError>{let codec=self.codec;self.codec=CodecId(0);let result=self.segment(kind,payload,control);self.codec=codec;result}
    /// 🏁️ Writes the exact literal chunk index, manifest, end segment and footer.
    pub fn finish(mut self,manifest:&Manifest,control:&mut NativeEncodeControl<'_>)->Result<Vec<u8>,PackError>{
        if !manifest.schema_name.is_empty(){return Err(PackError::RetainedMalformed{kind:ValueRefusalKind::InvalidValue,what:"manifest",offset:0,detail:"controlled document manifest requires its literal empty schema name"})}let count=self.chunks.len();let mut chunk_span=ByteRange{offset:0,len:0};if count!=0{let mut length=retained_varint_len(count as u64);control.scoped_stage(|control|{control.begin_stage(count)?;for chunk in &self.chunks{length=length.checked_add(retained_varint_len(chunk.offset)).and_then(|length|length.checked_add(retained_varint_len(chunk.stored_len))).and_then(|length|length.checked_add(retained_varint_len(chunk.raw_len))).and_then(|length|length.checked_add(36)).ok_or(PackError::LimitExceeded{kind:ValueRefusalKind::OwnershipLimit,limit:"Pack chunk table length overflow"})?;control.step()?;}Ok::<_,PackError>(())})?;let mut payload=control.allocate_vec::<u8>(length).map_err(PackError::ValueRefusal)?;let mut prefix=Prefix::new();prefix.varint(count as u64)?;payload.extend_from_slice(prefix.slice());control.scoped_stage(|control|{control.begin_stage(count)?;for chunk in &self.chunks{let mut prefix=Prefix::new();prefix.varint(chunk.offset)?;prefix.varint(chunk.stored_len)?;prefix.varint(chunk.raw_len)?;prefix.bytes(&chunk.crc32.to_le_bytes())?;prefix.bytes(&chunk.blake3)?;payload.extend_from_slice(prefix.slice());control.step()?;}Ok::<_,PackError>(())})?;let start=self.position();self.raw_segment(KIND_CHUNK_TABLE,&payload,control)?;chunk_span=ByteRange{offset:start,len:self.position()-start};}
        let mut prefix=Prefix::new();prefix.varint(0)?;prefix.bytes(&manifest.schema_hash)?;prefix.span(manifest.doc_span)?;prefix.varint(manifest.doc_frame_count)?;prefix.span(self.symbols_span)?;prefix.span(chunk_span)?;prefix.span(manifest.field_index_span)?;prefix.varint(manifest.uncompressed_body_len)?;prefix.varint(manifest.field_count)?;prefix.varint(count as u64)?;prefix.varint(self.symbol_count)?;let start=self.position();self.segment(KIND_MANIFEST,prefix.slice(),control)?;let manifest_length=self.position()-start;self.raw_segment(KIND_END,&[],control)?;let mut footer=Prefix::new();footer.bytes(&FOOTER_MAGIC)?;footer.bytes(&FORMAT_VERSION_MAJOR.to_le_bytes())?;footer.bytes(&FORMAT_VERSION_MINOR.to_le_bytes())?;footer.bytes(&self.required_flags.to_le_bytes())?;footer.bytes(&start.to_le_bytes())?;footer.bytes(&manifest_length.to_le_bytes())?;footer.bytes(&(self.position()+FOOTER_SIZE as u64).to_le_bytes())?;footer.bytes(self.document_hash.finalize().as_bytes())?;footer.bytes(&0u64.to_le_bytes())?;let crc=crc32c(footer.slice());footer.bytes(&crc.to_le_bytes())?;self.append(footer.slice(),control)?;Ok(self.bytes)
    }
}
